async (page) => {
  await page.evaluate(() => {
    window.forumName = 'women_shots';
    window.forumTitle = 'women_shots';
    window.forumDesc = 'Best candid shots of women in the wild';
    window.forumSidebar = 'Back angle shots, Front angle shots';
  });

  // Verify the variables were set
  const result = await page.evaluate(() => ({
    forumName: window.forumName,
    forumTitle: window.forumTitle,
    forumDesc: window.forumDesc,
    forumSidebar: window.forumSidebar
  }));

  return result;
}
